(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+t*0.15)*8 + Math.cos(sy*0.02-t*0.4)*6;
  const w2y = Math.cos(sy*0.028-t*0.35)*8 + Math.sin(sx*0.022+t*0.45)*6;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.38)*55, 0.075, 2.1, 0.0],
    [320+Math.cos(t*0.48)*110, 165+Math.sin(t*0.65)*55, 0.09, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*150, 115+Math.cos(t*0.45+1)*95, 0.055, 2.4, 2.4],
    [115+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.55+3)*65, 0.11, 1.6, 3.6],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 4.8],
    [240+Math.cos(t*0.32+5)*130, 205+Math.sin(t*0.5)*85, 0.085, 2.0, 0.8],
    [80+Math.sin(t*0.6+3)*70, 100+Math.cos(t*0.42+4)*60, 0.13, 1.4, 5.5],
    [400+Math.cos(t*0.33+2)*80, 190+Math.sin(t*0.72+1)*50, 0.07, 2.5, 2.0]
  ];
  let aS = 0, iS = 0, hS = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    const w = Math.sin(d*f - t*sp + ph);
    aS += w;
    iS += Math.sin(d*f*0.7 + t*sp*0.55 + 1.5 + ph);
    hS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0 + ph*0.5);
  }
  const n = 8;
  const act = aS/n, inh = iS/n, hab = hS/n;
  const bg1 = (Math.sin(wx*0.035+wy*0.022+t*0.7) + Math.sin(wx*0.028-wy*0.038+t*1.0))/2;
  const bg2 = Math.sin((wx+wy)*0.1+t*2.2)*0.25 + Math.sin((wx-wy)*0.085-t*1.8)*0.25;
  const bg3 = Math.sin(wx*0.065+t*1.5)*Math.cos(wy*0.055-t*1.2)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((wx-cx)**2 + (wy-cy)**2);
  const ang = Math.atan2(wy-cy, wx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.08-ang*2-t*2.5)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const edge1 = Math.sin(wx*0.14)*Math.sin(wy*0.14);
  const edge2 = Math.sin((wx+wy)*0.09+t*0.8)*0.5;
  const cell = (edge1 + edge2)*0.35;
  const micro = Math.sin(wx*0.3+t*3)*Math.sin(wy*0.3-t*2.5)*0.1;
  const rd1 = act - inh*0.65 + bg*0.25 + spiral;
  const rd2 = hab*0.4 - act*inh*0.3;
  const reaction = Math.tanh((rd1 + rd2)*2.0);
  const detail = Math.tanh((cell + micro)*1.8)*0.25;
  const blend = reaction*0.7 + detail*0.3;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[8,35,85],[12,65,115],[18,105,130],
    [45,145,125],[110,170,100],[180,175,65],[210,150,55],
    [195,100,60],[165,60,70],[120,35,75],[70,22,60],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r0 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.78 + Math.sin(reaction*Math.PI)*0.22;
  const edgeGlow = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const shimmer = 1.0 + Math.sin(reaction*8+t*4)*0.04*Math.abs(reaction);
  const m = lum * edgeGlow * shimmer;
  return [
    Math.min(255, r0*m)|0,
    Math.min(255, g0*m)|0,
    Math.min(255, b0*m)|0
  ];
}
